/* ============================================================================
Merchant Sales-Based Financing Strategy Simulator
Module 2.8 — Servicing Execution Simulation, Payment Processing
             & Account Lifecycle Control

Program     : 190_msbf_m2_8_servicing_payment_lifecycle_generation_v0_2.sql
Version     : v0.2

Purpose
-------
Materialize the accepted M2.7 source once; generate deterministic account
execution, a seven-event payment ledger with one return and one retry,
sixty-seven lifecycle transitions, scenario summaries, latest/archive
contracts, registry identities, 24 generation-evidence rows, and the
M2_8_GENERATED lifecycle state. Window functions compute cumulative payment
and exposure evidence.

Stage boundary
--------------
All servicing, payment, processor-reference, return, retry, and lifecycle
outputs are deterministic synthetic evidence. No real funds move; no bank or
routing data is used; no ACH/network transmission, external processor call,
merchant contact, write-off/collection/legal execution, external notice, or
production adverse action occurs.

Required result
---------------
generation_status = PASS; 367 canonical entities; zero mismatches.
============================================================================ */

BEGIN;
SET LOCAL work_mem='192MB';SET LOCAL lock_timeout='10s';SET LOCAL statement_timeout='60min';SET LOCAL jit=off;
DROP TABLE IF EXISTS _m28_result;
CREATE TEMP TABLE _m28_result(run_id bigint,run_status text,policy_rows bigint,outcome_rows bigint,action_rows bigint,lifecycle_state_rows bigint,reason_rows bigint,source_rows bigint,execution_rows bigint,payment_event_rows bigint,lifecycle_transition_rows bigint,portfolio_summary_rows bigint,latest_rows bigint,archive_rows bigint,comparison_rows bigint,registry_rows bigint,no_processing_required_rows bigint,temporary_processing_rows bigint,review_hold_rows bigint,settled_event_rows bigint,returned_event_rows bigint,retry_event_rows bigint,initial_transition_rows bigint,payment_transition_rows bigint,checkpoint_transition_rows bigint,processing_authorized_amount numeric(24,2),review_hold_amount numeric(24,2),standard_daily_payment_amount numeric(24,2),temporary_daily_payment_amount numeric(24,2),scheduled_payment_amount numeric(24,2),processed_payment_amount numeric(24,2),returned_payment_amount numeric(24,2),retry_payment_amount numeric(24,2),ending_simulated_exposure_amount numeric(24,2),expected_canonical_entities bigint,actual_canonical_entities bigint,row_level_mismatches bigint,stress_processing_permission_improvements bigint,stress_priority_improvements bigint,stress_exposure_improvements bigint,policy_set_hash text,outcome_set_hash text,action_set_hash text,lifecycle_state_set_hash text,reason_set_hash text,source_set_hash text,execution_set_hash text,payment_event_set_hash text,lifecycle_transition_set_hash text,portfolio_summary_set_hash text,latest_set_hash text,archive_set_hash text,contract_set_hash text,combined_set_hash text,generation_status text) ON COMMIT PRESERVE ROWS;

/* ============================================================================
Section 1 — Context and accepted source materialization
============================================================================ */
CREATE TEMP TABLE _m28_ctx ON COMMIT DROP AS
SELECT run.run_id,run.as_of_date,p.configuration_hash,p.servicing_cycle_days,p.synthetic_return_event_sequence,p.synthetic_retry_event_sequence,p.retry_catchup_multiplier,p.default_temporary_payment_factor,p.default_setup_duration_days,p.default_reassessment_interval_days,p.source_combined_set_hash
FROM msbf_ctl.run_registry run JOIN msbf_ctl.m2_8_policy_profile p ON p.module1_run_id=run.run_id
WHERE run.run_code='M1_V0_2_BASELINE_BUILD' AND run.run_version=1;
DO $ready$ BEGIN PERFORM msbf_ctl.m2_8_assert_generation_ready((SELECT run_id FROM _m28_ctx));END;$ready$;

CREATE TEMP TABLE _m28_source ON COMMIT DROP AS
SELECT s.module1_run_id,s.scenario_id,s.scenario_code,s.merchant_application_id,s.merchant_id,s.synthetic_account_id,s.synthetic_advance_id,
 s.operational_setup_outcome_code source_operational_setup_outcome_code,s.operational_setup_action_code source_operational_setup_action_code,
 s.account_setup_status_code source_setup_status_code,s.setup_authorized_flag source_setup_authorized_flag,
 s.setup_review_required_flag source_setup_review_required_flag,s.no_setup_required_flag source_no_setup_required_flag,
 s.source_recommended_action_exposure_amount::numeric(18,2) source_exposure_amount,
 s.synthetic_operational_case_id source_operational_case_id,s.synthetic_account_setup_id source_account_setup_id,
 s.synthetic_servicing_plan_id source_servicing_plan_id,s.operational_activation_date source_activation_date,
 s.next_reassessment_date source_reassessment_date,s.applied_temporary_payment_factor source_payment_factor,
 s.applied_setup_duration_days source_setup_duration_days,s.applied_reassessment_interval_days source_reassessment_interval_days,
 s.primary_setup_reason_code source_primary_reason_code,s.setup_reason_codes source_reason_codes,
 s.setup_parameter_payload source_setup_parameter_payload,s.contract_row_hash source_contract_row_hash,
 c.source_combined_set_hash,to_jsonb(s) source_payload,NULL::text row_hash
FROM msbf_m2.application_operational_activation_latest s CROSS JOIN _m28_ctx c WHERE s.module1_run_id=c.run_id;
UPDATE _m28_source s SET row_hash=msbf_ctl.m2_8_hash_jsonb(to_jsonb(s)-'row_hash') WHERE s.row_hash IS NULL;
CREATE UNIQUE INDEX ON _m28_source(module1_run_id,scenario_id,merchant_application_id);
CREATE INDEX ON _m28_source(module1_run_id,source_operational_setup_outcome_code);ANALYZE _m28_source;

/* ============================================================================
Section 2 — Exact account-level execution mapping
============================================================================ */
CREATE TEMP TABLE _m28_map ON COMMIT DROP AS
SELECT s.*,
 CASE
  WHEN source_operational_setup_outcome_code='NO_OPERATIONAL_SETUP_REQUIRED' AND source_operational_setup_action_code='CLOSE_WITHOUT_SETUP' AND source_setup_status_code='NOT_REQUIRED' THEN 'NO_SERVICING_EXECUTION_REQUIRED'
  WHEN source_operational_setup_outcome_code='STANDARD_SERVICING_SETUP_READY' THEN 'SIMULATED_STANDARD_PAYMENT_PROCESSING_ACTIVE'
  WHEN source_operational_setup_outcome_code='TEMPORARY_PAYMENT_ADJUSTMENT_SETUP_READY' AND source_operational_setup_action_code='CREATE_TEMPORARY_ADJUSTMENT_BLUEPRINT' AND source_setup_status_code='SIMULATED_BLUEPRINT_READY' THEN 'SIMULATED_TEMPORARY_PAYMENT_PROCESSING_ACTIVE'
  WHEN source_operational_setup_outcome_code='RESTRUCTURE_SETUP_READY' THEN 'SIMULATED_RESTRUCTURE_PAYMENT_PROCESSING_ACTIVE'
  WHEN source_operational_setup_outcome_code='CONTROLLED_RECOVERY_SETUP_READY' THEN 'SIMULATED_RECOVERY_PAYMENT_PROCESSING_ACTIVE'
  WHEN source_operational_setup_outcome_code='CHARGE_OFF_SETUP_READY' THEN 'SIMULATED_CHARGE_OFF_LIFECYCLE_CONTROL'
  ELSE 'SERVICING_EXECUTION_REVIEW_HOLD' END servicing_execution_outcome_code
FROM _m28_source s;
ALTER TABLE _m28_map ADD COLUMN servicing_execution_action_code text,ADD COLUMN servicing_execution_priority_rank integer,ADD COLUMN servicing_execution_queue_code text,ADD COLUMN processing_authorized_flag boolean,ADD COLUMN processing_review_required_flag boolean,ADD COLUMN no_processing_required_flag boolean,ADD COLUMN initial_lifecycle_state_code text,ADD COLUMN final_lifecycle_state_code text,ADD COLUMN primary_execution_reason_code text,ADD COLUMN execution_reason_codes jsonb;
UPDATE _m28_map m SET
 servicing_execution_action_code=CASE servicing_execution_outcome_code WHEN 'NO_SERVICING_EXECUTION_REQUIRED' THEN 'NO_PAYMENT_PROCESSING' WHEN 'SIMULATED_STANDARD_PAYMENT_PROCESSING_ACTIVE' THEN 'EXECUTE_STANDARD_SYNTHETIC_PAYMENT_CYCLE' WHEN 'SIMULATED_TEMPORARY_PAYMENT_PROCESSING_ACTIVE' THEN 'EXECUTE_TEMPORARY_SYNTHETIC_PAYMENT_CYCLE' WHEN 'SIMULATED_RESTRUCTURE_PAYMENT_PROCESSING_ACTIVE' THEN 'EXECUTE_RESTRUCTURE_SYNTHETIC_PAYMENT_CYCLE' WHEN 'SIMULATED_RECOVERY_PAYMENT_PROCESSING_ACTIVE' THEN 'EXECUTE_RECOVERY_SYNTHETIC_PAYMENT_CYCLE' WHEN 'SIMULATED_CHARGE_OFF_LIFECYCLE_CONTROL' THEN 'EXECUTE_CHARGE_OFF_LIFECYCLE_SIMULATION' ELSE 'HOLD_FOR_SERVICING_REVIEW' END,
 servicing_execution_priority_rank=CASE servicing_execution_outcome_code WHEN 'NO_SERVICING_EXECUTION_REQUIRED' THEN 0 WHEN 'SIMULATED_STANDARD_PAYMENT_PROCESSING_ACTIVE' THEN 1 WHEN 'SIMULATED_TEMPORARY_PAYMENT_PROCESSING_ACTIVE' THEN 2 WHEN 'SIMULATED_RESTRUCTURE_PAYMENT_PROCESSING_ACTIVE' THEN 3 WHEN 'SIMULATED_RECOVERY_PAYMENT_PROCESSING_ACTIVE' THEN 4 WHEN 'SIMULATED_CHARGE_OFF_LIFECYCLE_CONTROL' THEN 5 ELSE 9 END,
 servicing_execution_queue_code=CASE servicing_execution_outcome_code WHEN 'NO_SERVICING_EXECUTION_REQUIRED' THEN 'CLOSED_NO_PROCESSING' WHEN 'SIMULATED_STANDARD_PAYMENT_PROCESSING_ACTIVE' THEN 'STANDARD_PAYMENT_PROCESSING' WHEN 'SIMULATED_TEMPORARY_PAYMENT_PROCESSING_ACTIVE' THEN 'TEMPORARY_PAYMENT_PROCESSING' WHEN 'SIMULATED_RESTRUCTURE_PAYMENT_PROCESSING_ACTIVE' THEN 'RESTRUCTURE_PAYMENT_PROCESSING' WHEN 'SIMULATED_RECOVERY_PAYMENT_PROCESSING_ACTIVE' THEN 'RECOVERY_PAYMENT_PROCESSING' WHEN 'SIMULATED_CHARGE_OFF_LIFECYCLE_CONTROL' THEN 'CHARGE_OFF_LIFECYCLE_CONTROL' ELSE 'SERVICING_REVIEW_HOLD' END,
 processing_authorized_flag=servicing_execution_outcome_code IN ('SIMULATED_STANDARD_PAYMENT_PROCESSING_ACTIVE','SIMULATED_TEMPORARY_PAYMENT_PROCESSING_ACTIVE','SIMULATED_RESTRUCTURE_PAYMENT_PROCESSING_ACTIVE','SIMULATED_RECOVERY_PAYMENT_PROCESSING_ACTIVE','SIMULATED_CHARGE_OFF_LIFECYCLE_CONTROL'),
 processing_review_required_flag=servicing_execution_outcome_code='SERVICING_EXECUTION_REVIEW_HOLD',
 no_processing_required_flag=servicing_execution_outcome_code='NO_SERVICING_EXECUTION_REQUIRED',initial_lifecycle_state_code='NOT_STARTED',
 final_lifecycle_state_code=CASE WHEN servicing_execution_outcome_code='NO_SERVICING_EXECUTION_REQUIRED' THEN 'CLOSED_NO_PROCESSING_REQUIRED' WHEN servicing_execution_outcome_code='SERVICING_EXECUTION_REVIEW_HOLD' THEN 'SERVICING_REVIEW_HOLD' ELSE 'REASSESSMENT_DUE' END,
 primary_execution_reason_code=CASE servicing_execution_outcome_code WHEN 'NO_SERVICING_EXECUTION_REQUIRED' THEN 'M2_8_REASON_SOURCE_NO_PROCESSING' WHEN 'SIMULATED_STANDARD_PAYMENT_PROCESSING_ACTIVE' THEN 'M2_8_REASON_SOURCE_STANDARD_PROCESSING' WHEN 'SIMULATED_TEMPORARY_PAYMENT_PROCESSING_ACTIVE' THEN 'M2_8_REASON_SOURCE_TEMPORARY_PROCESSING' WHEN 'SIMULATED_RESTRUCTURE_PAYMENT_PROCESSING_ACTIVE' THEN 'M2_8_REASON_SOURCE_RESTRUCTURE_PROCESSING' WHEN 'SIMULATED_RECOVERY_PAYMENT_PROCESSING_ACTIVE' THEN 'M2_8_REASON_SOURCE_RECOVERY_PROCESSING' WHEN 'SIMULATED_CHARGE_OFF_LIFECYCLE_CONTROL' THEN 'M2_8_REASON_SOURCE_CHARGE_OFF_CONTROL' ELSE 'M2_8_REASON_SOURCE_REVIEW_HOLD' END
WHERE m.servicing_execution_action_code IS NULL;
UPDATE _m28_map m SET execution_reason_codes=to_jsonb(array_remove(ARRAY[m.primary_execution_reason_code,CASE WHEN m.processing_authorized_flag THEN 'M2_8_REASON_SETUP_AUTHORIZED' ELSE 'M2_8_REASON_SETUP_NOT_AUTHORIZED' END,CASE WHEN m.processing_authorized_flag AND m.source_payment_factor IS NOT NULL THEN 'M2_8_REASON_PAYMENT_FACTOR_PRESENT' WHEN m.processing_authorized_flag THEN 'M2_8_REASON_PAYMENT_FACTOR_DEFAULTED' END,CASE WHEN m.processing_authorized_flag AND m.source_setup_duration_days IS NOT NULL THEN 'M2_8_REASON_SETUP_DURATION_PRESENT' WHEN m.processing_authorized_flag THEN 'M2_8_REASON_SETUP_DURATION_DEFAULTED' END,CASE WHEN m.processing_authorized_flag AND m.source_reassessment_interval_days IS NOT NULL THEN 'M2_8_REASON_REASSESSMENT_PRESENT' WHEN m.processing_authorized_flag THEN 'M2_8_REASON_REASSESSMENT_DEFAULTED' END,'M2_8_REASON_SOURCE_HASH_PRESENT','M2_8_REASON_SOURCE_CONTRACT_ACCEPTED','M2_8_REASON_HISTORY_PRESERVED','M2_8_REASON_NO_BANK_DATA','M2_8_REASON_NO_NETWORK_TRANSMISSION','M2_8_REASON_NO_REAL_FUNDS_MOVEMENT','M2_8_REASON_SYNTHETIC_ONLY']::text[],NULL)) WHERE m.execution_reason_codes IS NULL;
CREATE UNIQUE INDEX ON _m28_map(module1_run_id,scenario_id,merchant_application_id);CREATE INDEX ON _m28_map(module1_run_id,servicing_execution_outcome_code);ANALYZE _m28_map;
DO $map_guard$ DECLARE v record;BEGIN SELECT count(*) source_rows,count(*) FILTER(WHERE no_processing_required_flag) no_processing_rows,count(*) FILTER(WHERE servicing_execution_outcome_code='SIMULATED_TEMPORARY_PAYMENT_PROCESSING_ACTIVE') temporary_rows,count(*) FILTER(WHERE processing_review_required_flag) review_rows,count(*) FILTER(WHERE processing_authorized_flag) authorized_rows,round(sum(CASE WHEN processing_authorized_flag THEN source_exposure_amount ELSE 0 END),2) authorized_amount,round(sum(CASE WHEN processing_review_required_flag THEN source_exposure_amount ELSE 0 END),2) review_amount,count(*) FILTER(WHERE processing_authorized_flag AND (source_servicing_plan_id IS NULL OR source_activation_date IS NULL OR source_reassessment_date IS NULL)) incomplete_authorized_rows INTO v FROM _m28_map;IF v.source_rows<>59 OR v.no_processing_rows<>57 OR v.temporary_rows<>1 OR v.review_rows<>1 OR v.authorized_rows<>1 OR v.authorized_amount<>518.04 OR v.review_amount<>461.69 OR v.incomplete_authorized_rows<>0 THEN RAISE EXCEPTION 'M2.8 exact source mapping failed: %.',row_to_json(v);END IF;END;$map_guard$;

INSERT INTO msbf_m2.servicing_execution_source_snapshot(module1_run_id,scenario_id,scenario_code,merchant_application_id,merchant_id,synthetic_account_id,synthetic_advance_id,source_operational_setup_outcome_code,source_operational_setup_action_code,source_setup_status_code,source_setup_authorized_flag,source_setup_review_required_flag,source_no_setup_required_flag,source_exposure_amount,source_operational_case_id,source_account_setup_id,source_servicing_plan_id,source_activation_date,source_reassessment_date,source_payment_factor,source_setup_duration_days,source_reassessment_interval_days,source_primary_reason_code,source_reason_codes,source_setup_parameter_payload,source_contract_row_hash,source_combined_set_hash,source_payload,row_hash)
SELECT module1_run_id,scenario_id,scenario_code,merchant_application_id,merchant_id,synthetic_account_id,synthetic_advance_id,source_operational_setup_outcome_code,source_operational_setup_action_code,source_setup_status_code,source_setup_authorized_flag,source_setup_review_required_flag,source_no_setup_required_flag,source_exposure_amount,source_operational_case_id,source_account_setup_id,source_servicing_plan_id,source_activation_date,source_reassessment_date,source_payment_factor,source_setup_duration_days,source_reassessment_interval_days,source_primary_reason_code,source_reason_codes,source_setup_parameter_payload,source_contract_row_hash,source_combined_set_hash,source_payload,row_hash FROM _m28_source;

/* ============================================================================
Section 3 — Seven-event payment ledger and window-function cumulative evidence
============================================================================ */
CREATE TEMP TABLE _m28_payment_seed ON COMMIT DROP AS
SELECT m.module1_run_id,m.scenario_id,m.scenario_code,m.merchant_application_id,m.synthetic_account_id,m.synthetic_advance_id,
 'MSBF_SERV_EXEC_'||upper(substr(md5(m.module1_run_id::text||'|'||m.scenario_id::text||'|'||m.merchant_application_id||'|M2_8_EXECUTION'),1,20)) synthetic_servicing_execution_id,
 m.source_servicing_plan_id synthetic_servicing_plan_id,g.event_sequence,(m.source_activation_date+g.event_sequence-1)::date event_date,
 CASE WHEN g.event_sequence=c.synthetic_return_event_sequence THEN 'SYNTHETIC_PAYMENT_RETURN' WHEN g.event_sequence=c.synthetic_retry_event_sequence THEN 'SYNTHETIC_RETRY_PAYMENT' ELSE 'SYNTHETIC_SCHEDULED_PAYMENT' END payment_event_type_code,
 CASE WHEN g.event_sequence=c.synthetic_return_event_sequence THEN 'SIMULATED_RETURNED' WHEN g.event_sequence=c.synthetic_retry_event_sequence THEN 'SIMULATED_RETRY_SETTLED' ELSE 'SIMULATED_SETTLED' END payment_status_code,
 round(m.source_exposure_amount/coalesce(m.source_setup_duration_days,c.default_setup_duration_days),2)::numeric(18,2) standard_daily_payment_amount,
 coalesce(m.source_payment_factor,c.default_temporary_payment_factor)::numeric(9,6) applied_payment_factor,
 round(round(m.source_exposure_amount/coalesce(m.source_setup_duration_days,c.default_setup_duration_days),2)*coalesce(m.source_payment_factor,c.default_temporary_payment_factor),2)::numeric(18,2) scheduled_payment_amount,
 CASE WHEN g.event_sequence=c.synthetic_retry_event_sequence THEN round(round(m.source_exposure_amount/coalesce(m.source_setup_duration_days,c.default_setup_duration_days),2)*coalesce(m.source_payment_factor,c.default_temporary_payment_factor),2) ELSE 0 END::numeric(18,2) retry_payment_amount,
 CASE WHEN g.event_sequence=c.synthetic_return_event_sequence THEN round(round(m.source_exposure_amount/coalesce(m.source_setup_duration_days,c.default_setup_duration_days),2)*coalesce(m.source_payment_factor,c.default_temporary_payment_factor),2) ELSE 0 END::numeric(18,2) returned_payment_amount,
 CASE WHEN g.event_sequence=c.synthetic_return_event_sequence THEN 0 WHEN g.event_sequence=c.synthetic_retry_event_sequence THEN round(round(m.source_exposure_amount/coalesce(m.source_setup_duration_days,c.default_setup_duration_days),2)*coalesce(m.source_payment_factor,c.default_temporary_payment_factor)*c.retry_catchup_multiplier,2) ELSE round(round(m.source_exposure_amount/coalesce(m.source_setup_duration_days,c.default_setup_duration_days),2)*coalesce(m.source_payment_factor,c.default_temporary_payment_factor),2) END::numeric(18,2) processed_payment_amount,
 CASE WHEN g.event_sequence=c.synthetic_retry_event_sequence THEN 'PAYMENT_RETURNED_PENDING_RETRY' WHEN g.event_sequence=c.synthetic_retry_event_sequence+1 THEN 'ACTIVE_AFTER_RETRY' ELSE 'ACTIVE_PAYMENT_PLAN' END lifecycle_state_before_code,
 CASE WHEN g.event_sequence=c.synthetic_return_event_sequence THEN 'PAYMENT_RETURNED_PENDING_RETRY' WHEN g.event_sequence=c.synthetic_retry_event_sequence THEN 'ACTIVE_AFTER_RETRY' ELSE 'ACTIVE_PAYMENT_PLAN' END lifecycle_state_after_code,
 CASE WHEN g.event_sequence=c.synthetic_return_event_sequence THEN 'M2_8_REASON_PAYMENT_RETURNED' WHEN g.event_sequence=c.synthetic_retry_event_sequence THEN 'M2_8_REASON_RETRY_SETTLED' ELSE 'M2_8_REASON_PAYMENT_SETTLED' END primary_event_reason_code,
 'MSBF_PAY_INSTR_'||upper(substr(md5(m.module1_run_id::text||'|'||m.scenario_id::text||'|'||m.merchant_application_id||'|'||g.event_sequence::text||'|M2_8_PAY'),1,20)) synthetic_payment_instruction_id,
 'MSBF_PROC_REF_'||upper(substr(md5(m.module1_run_id::text||'|'||m.scenario_id::text||'|'||m.merchant_application_id||'|'||g.event_sequence::text||'|M2_8_PROC'),1,20)) synthetic_processor_reference_id,
 m.source_exposure_amount,m.row_hash source_mapping_row_hash
FROM _m28_map m CROSS JOIN _m28_ctx c CROSS JOIN LATERAL generate_series(1,c.servicing_cycle_days) g(event_sequence)
WHERE m.processing_authorized_flag;
CREATE UNIQUE INDEX ON _m28_payment_seed(module1_run_id,scenario_id,merchant_application_id,event_sequence);ANALYZE _m28_payment_seed;

CREATE TEMP TABLE _m28_payment ON COMMIT DROP AS
SELECT s.module1_run_id,s.scenario_id,s.scenario_code,s.merchant_application_id,s.synthetic_account_id,s.synthetic_advance_id,s.synthetic_servicing_execution_id,s.synthetic_servicing_plan_id,s.event_sequence,s.event_date,s.payment_event_type_code,s.payment_status_code,s.standard_daily_payment_amount,s.applied_payment_factor,s.scheduled_payment_amount,s.retry_payment_amount,s.returned_payment_amount,s.processed_payment_amount,
 sum(s.processed_payment_amount) OVER(PARTITION BY s.module1_run_id,s.scenario_id,s.merchant_application_id ORDER BY s.event_sequence ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)::numeric(18,2) cumulative_processed_amount,
 greatest(s.source_exposure_amount-sum(s.processed_payment_amount) OVER(PARTITION BY s.module1_run_id,s.scenario_id,s.merchant_application_id ORDER BY s.event_sequence ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW),0)::numeric(18,2) simulated_outstanding_exposure_amount,
 s.lifecycle_state_before_code,s.lifecycle_state_after_code,s.primary_event_reason_code,s.synthetic_payment_instruction_id,s.synthetic_processor_reference_id,
 FALSE real_funds_moved_flag,FALSE bank_account_data_present_flag,FALSE ach_or_network_transmitted_flag,FALSE external_processor_called_flag,FALSE merchant_contact_executed_flag,FALSE external_notice_generated_flag,FALSE production_adverse_action_flag,
 s.source_mapping_row_hash source_execution_row_hash,NULL::text row_hash
FROM _m28_payment_seed s;
CREATE UNIQUE INDEX ON _m28_payment(module1_run_id,scenario_id,merchant_application_id,event_sequence);ANALYZE _m28_payment;
CREATE TEMP TABLE _m28_payment_agg ON COMMIT DROP AS
SELECT module1_run_id,scenario_id,merchant_application_id,count(*)::integer payment_event_count,count(*) FILTER(WHERE payment_status_code='SIMULATED_SETTLED')::integer settled_event_count,count(*) FILTER(WHERE payment_status_code='SIMULATED_RETURNED')::integer returned_event_count,count(*) FILTER(WHERE payment_status_code='SIMULATED_RETRY_SETTLED')::integer retry_event_count,max(standard_daily_payment_amount) standard_daily_payment_amount,max(scheduled_payment_amount) temporary_daily_payment_amount,round(sum(scheduled_payment_amount),2) scheduled_payment_amount,round(sum(processed_payment_amount),2) processed_payment_amount,round(sum(returned_payment_amount),2) returned_payment_amount,round(sum(retry_payment_amount),2) retry_payment_amount,min(simulated_outstanding_exposure_amount) ending_simulated_exposure_amount
FROM _m28_payment GROUP BY module1_run_id,scenario_id,merchant_application_id;
CREATE UNIQUE INDEX ON _m28_payment_agg(module1_run_id,scenario_id,merchant_application_id);ANALYZE _m28_payment_agg;

/* ============================================================================
Section 4 — Account-level execution and payment lineage finalization
============================================================================ */
CREATE TEMP TABLE _m28_execution ON COMMIT DROP AS
SELECT m.module1_run_id,m.scenario_id,m.scenario_code,m.merchant_application_id,m.merchant_id,m.synthetic_account_id,m.synthetic_advance_id,
 m.source_operational_setup_outcome_code,m.source_operational_setup_action_code,m.source_setup_status_code source_account_setup_status_code,m.source_exposure_amount,
 m.servicing_execution_outcome_code,m.servicing_execution_action_code,m.servicing_execution_priority_rank,m.servicing_execution_queue_code,
 m.processing_authorized_flag,m.processing_review_required_flag,m.no_processing_required_flag,
 'MSBF_SERV_EXEC_'||upper(substr(md5(m.module1_run_id::text||'|'||m.scenario_id::text||'|'||m.merchant_application_id||'|M2_8_EXECUTION'),1,20)) synthetic_servicing_execution_id,
 m.initial_lifecycle_state_code,m.final_lifecycle_state_code,coalesce(a.payment_event_count,0) payment_event_count,coalesce(a.settled_event_count,0) settled_event_count,coalesce(a.returned_event_count,0) returned_event_count,coalesce(a.retry_event_count,0) retry_event_count,
 coalesce(a.standard_daily_payment_amount,0)::numeric(18,2) standard_daily_payment_amount,coalesce(a.temporary_daily_payment_amount,0)::numeric(18,2) temporary_daily_payment_amount,coalesce(a.scheduled_payment_amount,0)::numeric(18,2) scheduled_payment_amount,coalesce(a.processed_payment_amount,0)::numeric(18,2) processed_payment_amount,coalesce(a.returned_payment_amount,0)::numeric(18,2) returned_payment_amount,coalesce(a.retry_payment_amount,0)::numeric(18,2) retry_payment_amount,
 CASE WHEN m.processing_authorized_flag THEN coalesce(a.ending_simulated_exposure_amount,m.source_exposure_amount) WHEN m.processing_review_required_flag THEN m.source_exposure_amount ELSE 0 END::numeric(18,2) ending_simulated_exposure_amount,
 m.primary_execution_reason_code,m.execution_reason_codes,FALSE real_funds_moved_flag,FALSE bank_account_data_present_flag,FALSE ach_or_network_transmitted_flag,FALSE external_processor_called_flag,FALSE merchant_contact_executed_flag,FALSE write_off_or_collection_flag,FALSE external_notice_generated_flag,FALSE production_adverse_action_flag,
 m.source_contract_row_hash,m.row_hash source_snapshot_row_hash,c.configuration_hash policy_configuration_hash,NULL::text row_hash
FROM _m28_map m LEFT JOIN _m28_payment_agg a ON a.module1_run_id=m.module1_run_id AND a.scenario_id=m.scenario_id AND a.merchant_application_id=m.merchant_application_id CROSS JOIN _m28_ctx c;
UPDATE _m28_execution e SET row_hash=msbf_ctl.m2_8_hash_jsonb(to_jsonb(e)-'row_hash') WHERE e.row_hash IS NULL;
UPDATE _m28_payment p SET source_execution_row_hash=e.row_hash,row_hash=NULL FROM _m28_execution e WHERE e.module1_run_id=p.module1_run_id AND e.scenario_id=p.scenario_id AND e.merchant_application_id=p.merchant_application_id;
UPDATE _m28_payment p SET row_hash=msbf_ctl.m2_8_hash_jsonb(to_jsonb(p)-'row_hash') WHERE p.row_hash IS NULL;
CREATE UNIQUE INDEX ON _m28_execution(module1_run_id,scenario_id,merchant_application_id);CREATE INDEX ON _m28_execution(module1_run_id,servicing_execution_outcome_code);ANALYZE _m28_execution;ANALYZE _m28_payment;
DO $payment_guard$ DECLARE v record;BEGIN SELECT count(*) payment_rows,count(*) FILTER(WHERE payment_status_code='SIMULATED_SETTLED') settled_rows,count(*) FILTER(WHERE payment_status_code='SIMULATED_RETURNED') returned_rows,count(*) FILTER(WHERE payment_status_code='SIMULATED_RETRY_SETTLED') retry_rows,round(max(standard_daily_payment_amount),2) standard_daily_amount,round(max(scheduled_payment_amount),2) temporary_daily_amount,round(sum(scheduled_payment_amount),2) scheduled_amount,round(sum(processed_payment_amount),2) processed_amount,round(sum(returned_payment_amount),2) returned_amount,round(sum(retry_payment_amount),2) retry_amount,round(min(simulated_outstanding_exposure_amount),2) ending_exposure,count(*) FILTER(WHERE real_funds_moved_flag OR bank_account_data_present_flag OR ach_or_network_transmitted_flag OR external_processor_called_flag OR merchant_contact_executed_flag OR external_notice_generated_flag OR production_adverse_action_flag) boundary_rows INTO v FROM _m28_payment;IF v.payment_rows<>7 OR v.settled_rows<>5 OR v.returned_rows<>1 OR v.retry_rows<>1 OR v.standard_daily_amount<>37 OR v.temporary_daily_amount<>27.75 OR v.scheduled_amount<>194.25 OR v.processed_amount<>194.25 OR v.returned_amount<>27.75 OR v.retry_amount<>27.75 OR v.ending_exposure<>323.79 OR v.boundary_rows<>0 THEN RAISE EXCEPTION 'M2.8 payment generation failed: %.',row_to_json(v);END IF;END;$payment_guard$;
DO $exec_guard$ DECLARE v record;BEGIN SELECT count(*) execution_rows,count(*) FILTER(WHERE no_processing_required_flag) no_processing_rows,count(*) FILTER(WHERE servicing_execution_outcome_code='SIMULATED_TEMPORARY_PAYMENT_PROCESSING_ACTIVE') temporary_rows,count(*) FILTER(WHERE processing_review_required_flag) review_rows,sum(payment_event_count) payment_rows,round(sum(processed_payment_amount),2) processed_amount,round(sum(ending_simulated_exposure_amount),2) ending_exposure,count(*) FILTER(WHERE real_funds_moved_flag OR bank_account_data_present_flag OR ach_or_network_transmitted_flag OR external_processor_called_flag OR merchant_contact_executed_flag OR write_off_or_collection_flag OR external_notice_generated_flag OR production_adverse_action_flag) boundary_rows INTO v FROM _m28_execution;IF v.execution_rows<>59 OR v.no_processing_rows<>57 OR v.temporary_rows<>1 OR v.review_rows<>1 OR v.payment_rows<>7 OR v.processed_amount<>194.25 OR v.ending_exposure<>785.48 OR v.boundary_rows<>0 THEN RAISE EXCEPTION 'M2.8 execution generation failed: %.',row_to_json(v);END IF;END;$exec_guard$;

INSERT INTO msbf_m2.application_servicing_execution_snapshot(module1_run_id,scenario_id,scenario_code,merchant_application_id,merchant_id,synthetic_account_id,synthetic_advance_id,source_operational_setup_outcome_code,source_operational_setup_action_code,source_account_setup_status_code,source_exposure_amount,servicing_execution_outcome_code,servicing_execution_action_code,servicing_execution_priority_rank,servicing_execution_queue_code,processing_authorized_flag,processing_review_required_flag,no_processing_required_flag,synthetic_servicing_execution_id,initial_lifecycle_state_code,final_lifecycle_state_code,payment_event_count,settled_event_count,returned_event_count,retry_event_count,standard_daily_payment_amount,temporary_daily_payment_amount,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,ending_simulated_exposure_amount,primary_execution_reason_code,execution_reason_codes,real_funds_moved_flag,bank_account_data_present_flag,ach_or_network_transmitted_flag,external_processor_called_flag,merchant_contact_executed_flag,write_off_or_collection_flag,external_notice_generated_flag,production_adverse_action_flag,source_contract_row_hash,source_snapshot_row_hash,policy_configuration_hash,row_hash)
SELECT module1_run_id,scenario_id,scenario_code,merchant_application_id,merchant_id,synthetic_account_id,synthetic_advance_id,source_operational_setup_outcome_code,source_operational_setup_action_code,source_account_setup_status_code,source_exposure_amount,servicing_execution_outcome_code,servicing_execution_action_code,servicing_execution_priority_rank,servicing_execution_queue_code,processing_authorized_flag,processing_review_required_flag,no_processing_required_flag,synthetic_servicing_execution_id,initial_lifecycle_state_code,final_lifecycle_state_code,payment_event_count,settled_event_count,returned_event_count,retry_event_count,standard_daily_payment_amount,temporary_daily_payment_amount,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,ending_simulated_exposure_amount,primary_execution_reason_code,execution_reason_codes,real_funds_moved_flag,bank_account_data_present_flag,ach_or_network_transmitted_flag,external_processor_called_flag,merchant_contact_executed_flag,write_off_or_collection_flag,external_notice_generated_flag,production_adverse_action_flag,source_contract_row_hash,source_snapshot_row_hash,policy_configuration_hash,row_hash FROM _m28_execution;
