SELECT module1_run_id,scenario_id,scenario_code,merchant_application_id,synthetic_account_id,synthetic_advance_id,synthetic_servicing_execution_id,synthetic_servicing_plan_id,event_sequence,event_date,payment_event_type_code,payment_status_code,standard_daily_payment_amount,applied_payment_factor,scheduled_payment_amount,retry_payment_amount,returned_payment_amount,processed_payment_amount,cumulative_processed_amount,simulated_outstanding_exposure_amount,lifecycle_state_before_code,lifecycle_state_after_code,primary_event_reason_code,synthetic_payment_instruction_id,synthetic_processor_reference_id,real_funds_moved_flag,bank_account_data_present_flag,ach_or_network_transmitted_flag,external_processor_called_flag,merchant_contact_executed_flag,external_notice_generated_flag,production_adverse_action_flag,source_execution_row_hash,row_hash FROM _m28_payment;

/* ============================================================================
Section 5 — Lifecycle transitions
============================================================================ */
CREATE TEMP TABLE _m28_transition(module1_run_id bigint,scenario_id bigint,scenario_code text,merchant_application_id text,synthetic_account_id text,synthetic_advance_id text,synthetic_servicing_execution_id text,transition_sequence integer,transition_date date,transition_type_code text,lifecycle_state_before_code text,lifecycle_state_after_code text,related_payment_event_sequence integer,related_payment_instruction_id text,primary_transition_reason_code text,real_funds_moved_flag boolean,production_account_state_flag boolean,external_system_update_flag boolean,source_execution_row_hash text,related_payment_event_row_hash text,row_hash text) ON COMMIT DROP;
INSERT INTO _m28_transition SELECT e.module1_run_id,e.scenario_id,e.scenario_code,e.merchant_application_id,e.synthetic_account_id,e.synthetic_advance_id,e.synthetic_servicing_execution_id,0,coalesce(s.source_activation_date,c.as_of_date)::date,'INITIAL_ACCOUNT_CONTROL','NOT_STARTED',CASE WHEN e.no_processing_required_flag THEN 'CLOSED_NO_PROCESSING_REQUIRED' WHEN e.processing_review_required_flag THEN 'SERVICING_REVIEW_HOLD' ELSE 'ACTIVE_PAYMENT_PLAN' END,NULL,NULL,CASE WHEN e.no_processing_required_flag THEN 'M2_8_REASON_LIFECYCLE_CLOSED_NO_PROCESSING' WHEN e.processing_review_required_flag THEN 'M2_8_REASON_LIFECYCLE_REVIEW_HOLD' ELSE 'M2_8_REASON_LIFECYCLE_OPENED' END,FALSE,FALSE,FALSE,e.row_hash,NULL,NULL FROM _m28_execution e JOIN _m28_source s ON s.module1_run_id=e.module1_run_id AND s.scenario_id=e.scenario_id AND s.merchant_application_id=e.merchant_application_id CROSS JOIN _m28_ctx c;
INSERT INTO _m28_transition SELECT p.module1_run_id,p.scenario_id,p.scenario_code,p.merchant_application_id,p.synthetic_account_id,p.synthetic_advance_id,p.synthetic_servicing_execution_id,p.event_sequence,p.event_date,CASE p.payment_status_code WHEN 'SIMULATED_RETURNED' THEN 'PAYMENT_RETURN_EVENT' WHEN 'SIMULATED_RETRY_SETTLED' THEN 'PAYMENT_RETRY_EVENT' ELSE 'PAYMENT_PROCESSING_EVENT' END,p.lifecycle_state_before_code,p.lifecycle_state_after_code,p.event_sequence,p.synthetic_payment_instruction_id,p.primary_event_reason_code,FALSE,FALSE,FALSE,e.row_hash,p.row_hash,NULL FROM _m28_payment p JOIN _m28_execution e ON e.module1_run_id=p.module1_run_id AND e.scenario_id=p.scenario_id AND e.merchant_application_id=p.merchant_application_id;
INSERT INTO _m28_transition SELECT e.module1_run_id,e.scenario_id,e.scenario_code,e.merchant_application_id,e.synthetic_account_id,e.synthetic_advance_id,e.synthetic_servicing_execution_id,c.servicing_cycle_days+1,coalesce(s.source_reassessment_date,s.source_activation_date+c.default_reassessment_interval_days)::date,'REASSESSMENT_CHECKPOINT','ACTIVE_PAYMENT_PLAN','REASSESSMENT_DUE',NULL,NULL,'M2_8_REASON_REASSESSMENT_DUE',FALSE,FALSE,FALSE,e.row_hash,NULL,NULL FROM _m28_execution e JOIN _m28_source s ON s.module1_run_id=e.module1_run_id AND s.scenario_id=e.scenario_id AND s.merchant_application_id=e.merchant_application_id CROSS JOIN _m28_ctx c WHERE e.processing_authorized_flag;
UPDATE _m28_transition t SET row_hash=msbf_ctl.m2_8_hash_jsonb(to_jsonb(t)-'row_hash') WHERE t.row_hash IS NULL;
CREATE UNIQUE INDEX ON _m28_transition(module1_run_id,scenario_id,merchant_application_id,transition_sequence);CREATE INDEX ON _m28_transition(module1_run_id,transition_type_code);ANALYZE _m28_transition;
DO $transition_guard$ DECLARE v record;BEGIN SELECT count(*) transition_rows,count(*) FILTER(WHERE transition_sequence=0) initial_rows,count(*) FILTER(WHERE transition_type_code IN ('PAYMENT_PROCESSING_EVENT','PAYMENT_RETURN_EVENT','PAYMENT_RETRY_EVENT')) payment_rows,count(*) FILTER(WHERE transition_type_code='REASSESSMENT_CHECKPOINT') checkpoint_rows,count(*) FILTER(WHERE real_funds_moved_flag OR production_account_state_flag OR external_system_update_flag) boundary_rows INTO v FROM _m28_transition;IF v.transition_rows<>67 OR v.initial_rows<>59 OR v.payment_rows<>7 OR v.checkpoint_rows<>1 OR v.boundary_rows<>0 THEN RAISE EXCEPTION 'M2.8 lifecycle generation failed: %.',row_to_json(v);END IF;END;$transition_guard$;
INSERT INTO msbf_m2.account_lifecycle_transition_snapshot(module1_run_id,scenario_id,scenario_code,merchant_application_id,synthetic_account_id,synthetic_advance_id,synthetic_servicing_execution_id,transition_sequence,transition_date,transition_type_code,lifecycle_state_before_code,lifecycle_state_after_code,related_payment_event_sequence,related_payment_instruction_id,primary_transition_reason_code,real_funds_moved_flag,production_account_state_flag,external_system_update_flag,source_execution_row_hash,related_payment_event_row_hash,row_hash)
SELECT module1_run_id,scenario_id,scenario_code,merchant_application_id,synthetic_account_id,synthetic_advance_id,synthetic_servicing_execution_id,transition_sequence,transition_date,transition_type_code,lifecycle_state_before_code,lifecycle_state_after_code,related_payment_event_sequence,related_payment_instruction_id,primary_transition_reason_code,real_funds_moved_flag,production_account_state_flag,external_system_update_flag,source_execution_row_hash,related_payment_event_row_hash,row_hash FROM _m28_transition;

/* ============================================================================
Section 6 — Portfolio, latest, archive, registry, canonical reconciliation
============================================================================ */
CREATE TEMP TABLE _m28_portfolio ON COMMIT DROP AS
WITH pa AS(SELECT module1_run_id,scenario_code,count(*) payment_event_rows,count(*) FILTER(WHERE payment_status_code='SIMULATED_SETTLED') settled_event_rows,count(*) FILTER(WHERE payment_status_code='SIMULATED_RETURNED') returned_event_rows,count(*) FILTER(WHERE payment_status_code='SIMULATED_RETRY_SETTLED') retry_event_rows,round(sum(scheduled_payment_amount),2) scheduled_payment_amount,round(sum(processed_payment_amount),2) processed_payment_amount,round(sum(returned_payment_amount),2) returned_payment_amount,round(sum(retry_payment_amount),2) retry_payment_amount FROM _m28_payment GROUP BY module1_run_id,scenario_code),ta AS(SELECT module1_run_id,scenario_code,count(*) lifecycle_transition_rows FROM _m28_transition GROUP BY module1_run_id,scenario_code)
SELECT e.module1_run_id,e.scenario_code,count(*) source_rows,count(*) FILTER(WHERE e.processing_authorized_flag) processing_authorized_rows,count(*) FILTER(WHERE e.processing_review_required_flag) review_hold_rows,count(*) FILTER(WHERE e.no_processing_required_flag) no_processing_required_rows,coalesce(pa.payment_event_rows,0) payment_event_rows,coalesce(pa.settled_event_rows,0) settled_event_rows,coalesce(pa.returned_event_rows,0) returned_event_rows,coalesce(pa.retry_event_rows,0) retry_event_rows,ta.lifecycle_transition_rows,coalesce(pa.scheduled_payment_amount,0)::numeric(24,2) scheduled_payment_amount,coalesce(pa.processed_payment_amount,0)::numeric(24,2) processed_payment_amount,coalesce(pa.returned_payment_amount,0)::numeric(24,2) returned_payment_amount,coalesce(pa.retry_payment_amount,0)::numeric(24,2) retry_payment_amount,round(sum(e.ending_simulated_exposure_amount),2)::numeric(24,2) ending_simulated_exposure_amount,max(e.servicing_execution_priority_rank) maximum_execution_priority_rank,NULL::text row_hash
FROM _m28_execution e LEFT JOIN pa ON pa.module1_run_id=e.module1_run_id AND pa.scenario_code=e.scenario_code JOIN ta ON ta.module1_run_id=e.module1_run_id AND ta.scenario_code=e.scenario_code GROUP BY e.module1_run_id,e.scenario_code,pa.payment_event_rows,pa.settled_event_rows,pa.returned_event_rows,pa.retry_event_rows,ta.lifecycle_transition_rows,pa.scheduled_payment_amount,pa.processed_payment_amount,pa.returned_payment_amount,pa.retry_payment_amount;
UPDATE _m28_portfolio p SET row_hash=msbf_ctl.m2_8_hash_jsonb(to_jsonb(p)-'row_hash') WHERE p.row_hash IS NULL;
INSERT INTO msbf_m2.servicing_execution_portfolio_summary(module1_run_id,scenario_code,source_rows,processing_authorized_rows,review_hold_rows,no_processing_required_rows,payment_event_rows,settled_event_rows,returned_event_rows,retry_event_rows,lifecycle_transition_rows,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,ending_simulated_exposure_amount,maximum_execution_priority_rank,row_hash)
SELECT module1_run_id,scenario_code,source_rows,processing_authorized_rows,review_hold_rows,no_processing_required_rows,payment_event_rows,settled_event_rows,returned_event_rows,retry_event_rows,lifecycle_transition_rows,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,ending_simulated_exposure_amount,maximum_execution_priority_rank,row_hash FROM _m28_portfolio;

CREATE TEMP TABLE _m28_latest ON COMMIT DROP AS
SELECT e.module1_run_id,'M2_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_CONSUMPTION'::text contract_code,1::integer contract_version,'M2_8_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_SCHEMA_V1'::text schema_version,'M2_8_METHOD_V1'::text methodology_version,e.scenario_id,e.scenario_code,e.merchant_application_id,e.merchant_id,e.synthetic_account_id,e.synthetic_advance_id,e.source_operational_setup_outcome_code,e.source_operational_setup_action_code,e.source_account_setup_status_code,e.source_exposure_amount,e.servicing_execution_outcome_code,e.servicing_execution_action_code,e.servicing_execution_priority_rank,e.servicing_execution_queue_code,e.processing_authorized_flag,e.processing_review_required_flag,e.no_processing_required_flag,e.synthetic_servicing_execution_id,e.initial_lifecycle_state_code,e.final_lifecycle_state_code,e.payment_event_count,e.settled_event_count,e.returned_event_count,e.retry_event_count,e.standard_daily_payment_amount,e.temporary_daily_payment_amount,e.scheduled_payment_amount,e.processed_payment_amount,e.returned_payment_amount,e.retry_payment_amount,e.ending_simulated_exposure_amount,e.primary_execution_reason_code,e.execution_reason_codes,e.source_contract_row_hash,e.source_snapshot_row_hash,e.row_hash execution_snapshot_row_hash,e.policy_configuration_hash,NULL::text contract_row_hash FROM _m28_execution e;
UPDATE _m28_latest l SET contract_row_hash=msbf_ctl.m2_8_hash_jsonb(to_jsonb(l)-'contract_row_hash') WHERE l.contract_row_hash IS NULL;
DO $latest_guard$ DECLARE n bigint;i bigint;BEGIN SELECT count(*) FILTER(WHERE contract_row_hash IS NULL),count(*) FILTER(WHERE contract_row_hash IS NOT NULL AND (length(contract_row_hash)<>32 OR contract_row_hash !~ '^[0-9a-f]+$')) INTO n,i FROM _m28_latest;IF n<>0 OR i<>0 THEN RAISE EXCEPTION 'M2.8 latest staging hash failed: null %, invalid %.',n,i;END IF;END;$latest_guard$;
CREATE UNIQUE INDEX ON _m28_latest(module1_run_id,scenario_id,merchant_application_id);ANALYZE _m28_latest;
INSERT INTO msbf_m2.application_servicing_execution_latest(module1_run_id,contract_code,contract_version,schema_version,methodology_version,scenario_id,scenario_code,merchant_application_id,merchant_id,synthetic_account_id,synthetic_advance_id,source_operational_setup_outcome_code,source_operational_setup_action_code,source_account_setup_status_code,source_exposure_amount,servicing_execution_outcome_code,servicing_execution_action_code,servicing_execution_priority_rank,servicing_execution_queue_code,processing_authorized_flag,processing_review_required_flag,no_processing_required_flag,synthetic_servicing_execution_id,initial_lifecycle_state_code,final_lifecycle_state_code,payment_event_count,settled_event_count,returned_event_count,retry_event_count,standard_daily_payment_amount,temporary_daily_payment_amount,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,ending_simulated_exposure_amount,primary_execution_reason_code,execution_reason_codes,source_contract_row_hash,source_snapshot_row_hash,execution_snapshot_row_hash,policy_configuration_hash,contract_row_hash)
SELECT module1_run_id,contract_code,contract_version,schema_version,methodology_version,scenario_id,scenario_code,merchant_application_id,merchant_id,synthetic_account_id,synthetic_advance_id,source_operational_setup_outcome_code,source_operational_setup_action_code,source_account_setup_status_code,source_exposure_amount,servicing_execution_outcome_code,servicing_execution_action_code,servicing_execution_priority_rank,servicing_execution_queue_code,processing_authorized_flag,processing_review_required_flag,no_processing_required_flag,synthetic_servicing_execution_id,initial_lifecycle_state_code,final_lifecycle_state_code,payment_event_count,settled_event_count,returned_event_count,retry_event_count,standard_daily_payment_amount,temporary_daily_payment_amount,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,ending_simulated_exposure_amount,primary_execution_reason_code,execution_reason_codes,source_contract_row_hash,source_snapshot_row_hash,execution_snapshot_row_hash,policy_configuration_hash,contract_row_hash FROM _m28_latest;

CREATE TEMP TABLE _m28_archive ON COMMIT DROP AS SELECT l.*,to_jsonb(l) contract_payload,NULL::text archive_row_hash FROM _m28_latest l;
