INSERT INTO msbf_m2.application_servicing_execution_archive(module1_run_id,contract_code,contract_version,schema_version,methodology_version,scenario_id,scenario_code,merchant_application_id,merchant_id,synthetic_account_id,synthetic_advance_id,source_operational_setup_outcome_code,source_operational_setup_action_code,source_account_setup_status_code,source_exposure_amount,servicing_execution_outcome_code,servicing_execution_action_code,servicing_execution_priority_rank,servicing_execution_queue_code,processing_authorized_flag,processing_review_required_flag,no_processing_required_flag,synthetic_servicing_execution_id,initial_lifecycle_state_code,final_lifecycle_state_code,payment_event_count,settled_event_count,returned_event_count,retry_event_count,standard_daily_payment_amount,temporary_daily_payment_amount,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,ending_simulated_exposure_amount,primary_execution_reason_code,execution_reason_codes,source_contract_row_hash,source_snapshot_row_hash,execution_snapshot_row_hash,policy_configuration_hash,contract_row_hash,contract_payload,archive_row_hash)
SELECT module1_run_id,contract_code,contract_version,schema_version,methodology_version,scenario_id,scenario_code,merchant_application_id,merchant_id,synthetic_account_id,synthetic_advance_id,source_operational_setup_outcome_code,source_operational_setup_action_code,source_account_setup_status_code,source_exposure_amount,servicing_execution_outcome_code,servicing_execution_action_code,servicing_execution_priority_rank,servicing_execution_queue_code,processing_authorized_flag,processing_review_required_flag,no_processing_required_flag,synthetic_servicing_execution_id,initial_lifecycle_state_code,final_lifecycle_state_code,payment_event_count,settled_event_count,returned_event_count,retry_event_count,standard_daily_payment_amount,temporary_daily_payment_amount,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,ending_simulated_exposure_amount,primary_execution_reason_code,execution_reason_codes,source_contract_row_hash,source_snapshot_row_hash,execution_snapshot_row_hash,policy_configuration_hash,contract_row_hash,contract_payload,archive_row_hash FROM _m28_archive;

