CREATE TEMP TABLE _m28_hash ON COMMIT DROP AS SELECT
 (SELECT md5(string_agg(row_hash,'|' ORDER BY module1_run_id)) FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_ctx)) policy_set_hash,
 (SELECT md5(string_agg(row_hash,'|' ORDER BY servicing_execution_outcome_rank,servicing_execution_outcome_code)) FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_ctx)) outcome_set_hash,
 (SELECT md5(string_agg(row_hash,'|' ORDER BY servicing_execution_action_rank,servicing_execution_action_code)) FROM msbf_m2.servicing_execution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m28_ctx)) action_set_hash,
 (SELECT md5(string_agg(row_hash,'|' ORDER BY lifecycle_state_rank,lifecycle_state_code)) FROM msbf_m2.account_lifecycle_state_definition WHERE module1_run_id=(SELECT run_id FROM _m28_ctx)) lifecycle_state_set_hash,
 (SELECT md5(string_agg(row_hash,'|' ORDER BY servicing_execution_reason_code)) FROM msbf_m2.servicing_execution_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m28_ctx)) reason_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||row_hash,'|' ORDER BY scenario_id,merchant_application_id)) FROM _m28_source) source_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||row_hash,'|' ORDER BY scenario_id,merchant_application_id)) FROM _m28_execution) execution_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||event_sequence::text||'|'||row_hash,'|' ORDER BY scenario_id,merchant_application_id,event_sequence)) FROM _m28_payment) payment_event_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||transition_sequence::text||'|'||row_hash,'|' ORDER BY scenario_id,merchant_application_id,transition_sequence)) FROM _m28_transition) lifecycle_transition_set_hash,
 (SELECT md5(string_agg(scenario_code||'|'||row_hash,'|' ORDER BY scenario_code)) FROM _m28_portfolio) portfolio_summary_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||contract_row_hash,'|' ORDER BY scenario_id,merchant_application_id)) FROM _m28_latest) latest_set_hash,
 (SELECT md5(string_agg(scenario_id::text||'|'||merchant_application_id||'|'||archive_row_hash,'|' ORDER BY scenario_id,merchant_application_id)) FROM _m28_archive) archive_set_hash;

CREATE TEMP TABLE _m28_registry ON COMMIT DROP AS
SELECT c.run_id module1_run_id,'M2_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_CONSUMPTION'::text contract_code,1 contract_version,'M2_8_SERVICING_EXECUTION_PAYMENT_LIFECYCLE_SCHEMA_V1'::text schema_version,'M2_8_METHOD_V1'::text methodology_version,'M2_OPERATIONAL_ACTIVATION_ACCOUNT_SETUP_CONSUMPTION'::text source_contract_code,1 source_contract_version,'M2_7_OPERATIONAL_ACTIVATION_ACCOUNT_SETUP_SCHEMA_V1'::text source_schema_version,'M2_7_OPERATIONAL_ACTIVATION_ACCOUNT_SETUP'::text source_acceptance_gate_id,'c8e3a472afd2a16b1183677324e9db98'::text source_combined_set_hash,c.configuration_hash policy_configuration_hash,
 1::bigint policy_rows,7::bigint outcome_rows,7::bigint action_rows,7::bigint lifecycle_state_rows,32::bigint reason_rows,59::bigint source_rows,59::bigint execution_rows,7::bigint payment_event_rows,67::bigint lifecycle_transition_rows,2::bigint portfolio_summary_rows,59::bigint latest_rows,59::bigint archive_rows,
 (SELECT count(*) FROM msbf_m2.v_m2_8_matched_scenario_comparison WHERE module1_run_id=c.run_id)::bigint comparison_rows,1::bigint registry_rows,367::bigint canonical_entities,
 (SELECT count(*) FROM _m28_execution WHERE no_processing_required_flag)::bigint no_processing_required_rows,(SELECT count(*) FROM _m28_execution WHERE servicing_execution_outcome_code='SIMULATED_TEMPORARY_PAYMENT_PROCESSING_ACTIVE')::bigint temporary_processing_rows,(SELECT count(*) FROM _m28_execution WHERE processing_review_required_flag)::bigint review_hold_rows,
 (SELECT count(*) FROM _m28_payment WHERE payment_status_code='SIMULATED_SETTLED')::bigint settled_event_rows,(SELECT count(*) FROM _m28_payment WHERE payment_status_code='SIMULATED_RETURNED')::bigint returned_event_rows,(SELECT count(*) FROM _m28_payment WHERE payment_status_code='SIMULATED_RETRY_SETTLED')::bigint retry_event_rows,
 (SELECT count(*) FROM _m28_transition WHERE transition_sequence=0)::bigint initial_transition_rows,(SELECT count(*) FROM _m28_transition WHERE transition_type_code IN ('PAYMENT_PROCESSING_EVENT','PAYMENT_RETURN_EVENT','PAYMENT_RETRY_EVENT'))::bigint payment_transition_rows,(SELECT count(*) FROM _m28_transition WHERE transition_type_code='REASSESSMENT_CHECKPOINT')::bigint checkpoint_transition_rows,
 (SELECT round(sum(CASE WHEN processing_authorized_flag THEN source_exposure_amount ELSE 0 END),2) FROM _m28_execution)::numeric(24,2) processing_authorized_amount,(SELECT round(sum(CASE WHEN processing_review_required_flag THEN source_exposure_amount ELSE 0 END),2) FROM _m28_execution)::numeric(24,2) review_hold_amount,
 (SELECT round(sum(scheduled_payment_amount),2) FROM _m28_payment)::numeric(24,2) scheduled_payment_amount,(SELECT round(sum(processed_payment_amount),2) FROM _m28_payment)::numeric(24,2) processed_payment_amount,(SELECT round(sum(returned_payment_amount),2) FROM _m28_payment)::numeric(24,2) returned_payment_amount,(SELECT round(sum(retry_payment_amount),2) FROM _m28_payment)::numeric(24,2) retry_payment_amount,(SELECT round(sum(ending_simulated_exposure_amount),2) FROM _m28_execution)::numeric(24,2) ending_simulated_exposure_amount,
 h.policy_set_hash,h.outcome_set_hash,h.action_set_hash,h.lifecycle_state_set_hash,h.reason_set_hash,h.source_set_hash,h.execution_set_hash,h.payment_event_set_hash,h.lifecycle_transition_set_hash,h.portfolio_summary_set_hash,h.latest_set_hash,h.archive_set_hash,NULL::text contract_set_hash,NULL::text combined_set_hash,'GENERATED'::text contract_status,clock_timestamp() generated_at,NULL::timestamptz validated_at,NULL::timestamptz accepted_at,NULL::text row_hash
FROM _m28_ctx c CROSS JOIN _m28_hash h;
UPDATE _m28_registry r SET row_hash=msbf_ctl.m2_8_registry_row_hash(to_jsonb(r)) WHERE r.row_hash IS NULL;
UPDATE _m28_registry r SET contract_set_hash=md5(r.row_hash) WHERE r.contract_set_hash IS NULL;
CREATE TEMP TABLE _m28_canonical(entity_type text,entity_key text,row_hash text,PRIMARY KEY(entity_type,entity_key)) ON COMMIT DROP;
INSERT INTO _m28_canonical SELECT 'POLICY',policy_code||'|v'||policy_version,row_hash FROM msbf_ctl.m2_8_policy_profile WHERE module1_run_id=(SELECT run_id FROM _m28_ctx)
UNION ALL SELECT 'OUTCOME_DEFINITION',servicing_execution_outcome_code,row_hash FROM msbf_m2.servicing_execution_outcome_definition WHERE module1_run_id=(SELECT run_id FROM _m28_ctx)
UNION ALL SELECT 'ACTION_DEFINITION',servicing_execution_action_code,row_hash FROM msbf_m2.servicing_execution_action_definition WHERE module1_run_id=(SELECT run_id FROM _m28_ctx)
UNION ALL SELECT 'LIFECYCLE_STATE_DEFINITION',lifecycle_state_code,row_hash FROM msbf_m2.account_lifecycle_state_definition WHERE module1_run_id=(SELECT run_id FROM _m28_ctx)
UNION ALL SELECT 'REASON_DEFINITION',servicing_execution_reason_code,row_hash FROM msbf_m2.servicing_execution_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m28_ctx)
UNION ALL SELECT 'SOURCE',scenario_id::text||'|'||merchant_application_id,row_hash FROM _m28_source
UNION ALL SELECT 'EXECUTION',scenario_id::text||'|'||merchant_application_id,row_hash FROM _m28_execution
UNION ALL SELECT 'PAYMENT_EVENT',scenario_id::text||'|'||merchant_application_id||'|'||event_sequence,row_hash FROM _m28_payment
UNION ALL SELECT 'LIFECYCLE_TRANSITION',scenario_id::text||'|'||merchant_application_id||'|'||transition_sequence,row_hash FROM _m28_transition
UNION ALL SELECT 'PORTFOLIO_SUMMARY',scenario_code,row_hash FROM _m28_portfolio
UNION ALL SELECT 'LATEST',scenario_id::text||'|'||merchant_application_id,contract_row_hash FROM _m28_latest
UNION ALL SELECT 'ARCHIVE',scenario_id::text||'|'||merchant_application_id,archive_row_hash FROM _m28_archive
UNION ALL SELECT 'REGISTRY',contract_code||'|v'||contract_version,row_hash FROM _m28_registry;
UPDATE _m28_registry r SET combined_set_hash=(SELECT md5(string_agg(entity_type||'|'||entity_key||'|'||row_hash,'|' ORDER BY entity_type,entity_key)) FROM _m28_canonical) WHERE r.combined_set_hash IS NULL;
INSERT INTO msbf_ctl.m2_8_servicing_execution_contract_registry(module1_run_id,contract_code,contract_version,schema_version,methodology_version,source_contract_code,source_contract_version,source_schema_version,source_acceptance_gate_id,source_combined_set_hash,policy_configuration_hash,policy_rows,outcome_rows,action_rows,lifecycle_state_rows,reason_rows,source_rows,execution_rows,payment_event_rows,lifecycle_transition_rows,portfolio_summary_rows,latest_rows,archive_rows,comparison_rows,registry_rows,canonical_entities,no_processing_required_rows,temporary_processing_rows,review_hold_rows,settled_event_rows,returned_event_rows,retry_event_rows,initial_transition_rows,payment_transition_rows,checkpoint_transition_rows,processing_authorized_amount,review_hold_amount,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,ending_simulated_exposure_amount,policy_set_hash,outcome_set_hash,action_set_hash,lifecycle_state_set_hash,reason_set_hash,source_set_hash,execution_set_hash,payment_event_set_hash,lifecycle_transition_set_hash,portfolio_summary_set_hash,latest_set_hash,archive_set_hash,contract_set_hash,combined_set_hash,contract_status,generated_at,validated_at,accepted_at,row_hash)
SELECT module1_run_id,contract_code,contract_version,schema_version,methodology_version,source_contract_code,source_contract_version,source_schema_version,source_acceptance_gate_id,source_combined_set_hash,policy_configuration_hash,policy_rows,outcome_rows,action_rows,lifecycle_state_rows,reason_rows,source_rows,execution_rows,payment_event_rows,lifecycle_transition_rows,portfolio_summary_rows,latest_rows,archive_rows,comparison_rows,registry_rows,canonical_entities,no_processing_required_rows,temporary_processing_rows,review_hold_rows,settled_event_rows,returned_event_rows,retry_event_rows,initial_transition_rows,payment_transition_rows,checkpoint_transition_rows,processing_authorized_amount,review_hold_amount,scheduled_payment_amount,processed_payment_amount,returned_payment_amount,retry_payment_amount,ending_simulated_exposure_amount,policy_set_hash,outcome_set_hash,action_set_hash,lifecycle_state_set_hash,reason_set_hash,source_set_hash,execution_set_hash,payment_event_set_hash,lifecycle_transition_set_hash,portfolio_summary_set_hash,latest_set_hash,archive_set_hash,contract_set_hash,combined_set_hash,contract_status,generated_at,validated_at,accepted_at,row_hash FROM _m28_registry;

CREATE TEMP TABLE _m28_mismatch ON COMMIT DROP AS SELECT coalesce(e.entity_type,a.entity_type) entity_type,coalesce(e.entity_key,a.entity_key) entity_key,e.row_hash expected_hash,a.row_hash actual_hash FROM _m28_canonical e FULL JOIN(SELECT entity_type,entity_key,row_hash FROM msbf_m2.v_m2_8_canonical_entity WHERE module1_run_id=(SELECT run_id FROM _m28_ctx)) a ON a.entity_type=e.entity_type AND a.entity_key=e.entity_key WHERE e.row_hash IS DISTINCT FROM a.row_hash;
CREATE TEMP TABLE _m28_diag ON COMMIT PRESERVE ROWS AS SELECT (SELECT count(*) FROM _m28_canonical)::bigint expected_canonical_entities,(SELECT count(*) FROM msbf_m2.v_m2_8_canonical_entity WHERE module1_run_id=(SELECT run_id FROM _m28_ctx))::bigint actual_canonical_entities,(SELECT count(*) FROM _m28_mismatch)::bigint row_level_mismatches,(SELECT count(*) FROM msbf_m2.v_m2_8_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m28_ctx))::bigint comparison_rows,(SELECT count(*) FROM msbf_m2.v_m2_8_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m28_ctx) AND stress_processing_permission_improvement_flag)::bigint stress_processing_permission_improvements,(SELECT count(*) FROM msbf_m2.v_m2_8_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m28_ctx) AND stress_priority_improvement_flag)::bigint stress_priority_improvements,(SELECT count(*) FROM msbf_m2.v_m2_8_matched_scenario_comparison WHERE module1_run_id=(SELECT run_id FROM _m28_ctx) AND stress_exposure_improvement_flag)::bigint stress_exposure_improvements;
DO $recon$ DECLARE v record;BEGIN SELECT * INTO v FROM _m28_diag;IF v.expected_canonical_entities<>367 OR v.actual_canonical_entities<>367 OR v.row_level_mismatches<>0 OR v.comparison_rows<>15 OR v.stress_processing_permission_improvements<>0 OR v.stress_priority_improvements<>0 OR v.stress_exposure_improvements<>0 THEN RAISE EXCEPTION 'M2.8 deterministic reconciliation failed: %.',row_to_json(v);END IF;END;$recon$;

/* ============================================================================
Section 7 — Generation evidence and lifecycle transition
============================================================================ */
CREATE TEMP TABLE _m28_evidence(run_id bigint,evidence_code text,segment_key text,metric_name text,metric_value_numeric numeric(28,10),metric_value_text text,unit_code text,status text,interpretation text,CHECK(num_nonnulls(metric_value_numeric,metric_value_text)=1)) ON COMMIT DROP;
INSERT INTO _m28_evidence SELECT r.module1_run_id,v.evidence_code,'PORTFOLIO',v.metric_name,v.numeric_value,v.text_value,v.unit_code,'PASS',v.interpretation FROM _m28_registry r CROSS JOIN LATERAL(VALUES
('M2_8_POLICY_SET_HASH','POLICY_SET_HASH',NULL::numeric(28,10),r.policy_set_hash,'HASH','M2.8 policy set hash.'),('M2_8_OUTCOME_SET_HASH','OUTCOME_SET_HASH',NULL::numeric(28,10),r.outcome_set_hash,'HASH','Outcome set hash.'),('M2_8_ACTION_SET_HASH','ACTION_SET_HASH',NULL::numeric(28,10),r.action_set_hash,'HASH','Action set hash.'),('M2_8_LIFECYCLE_STATE_SET_HASH','LIFECYCLE_STATE_SET_HASH',NULL::numeric(28,10),r.lifecycle_state_set_hash,'HASH','Lifecycle-state set hash.'),('M2_8_REASON_SET_HASH','REASON_SET_HASH',NULL::numeric(28,10),r.reason_set_hash,'HASH','Reason set hash.'),('M2_8_SOURCE_SET_HASH','SOURCE_SET_HASH',NULL::numeric(28,10),r.source_set_hash,'HASH','Source set hash.'),('M2_8_EXECUTION_SET_HASH','EXECUTION_SET_HASH',NULL::numeric(28,10),r.execution_set_hash,'HASH','Execution set hash.'),('M2_8_PAYMENT_EVENT_SET_HASH','PAYMENT_EVENT_SET_HASH',NULL::numeric(28,10),r.payment_event_set_hash,'HASH','Payment-event set hash.'),('M2_8_LIFECYCLE_TRANSITION_SET_HASH','LIFECYCLE_TRANSITION_SET_HASH',NULL::numeric(28,10),r.lifecycle_transition_set_hash,'HASH','Lifecycle-transition set hash.'),('M2_8_PORTFOLIO_SET_HASH','PORTFOLIO_SET_HASH',NULL::numeric(28,10),r.portfolio_summary_set_hash,'HASH','Portfolio set hash.'),('M2_8_LATEST_SET_HASH','LATEST_SET_HASH',NULL::numeric(28,10),r.latest_set_hash,'HASH','Latest set hash.'),('M2_8_ARCHIVE_SET_HASH','ARCHIVE_SET_HASH',NULL::numeric(28,10),r.archive_set_hash,'HASH','Archive set hash.'),('M2_8_CONTRACT_SET_HASH','CONTRACT_SET_HASH',NULL::numeric(28,10),r.contract_set_hash,'HASH','Contract set hash.'),('M2_8_COMBINED_SET_HASH','COMBINED_SET_HASH',NULL::numeric(28,10),r.combined_set_hash,'HASH','Combined canonical hash.'),
('M2_8_SOURCE_ROWS','SOURCE_ROWS',r.source_rows::numeric,NULL,'ROWS','Source rows.'),('M2_8_EXECUTION_ROWS','EXECUTION_ROWS',r.execution_rows::numeric,NULL,'ROWS','Execution rows.'),('M2_8_PAYMENT_EVENT_ROWS','PAYMENT_EVENT_ROWS',r.payment_event_rows::numeric,NULL,'ROWS','Payment events.'),('M2_8_LIFECYCLE_TRANSITION_ROWS','LIFECYCLE_TRANSITION_ROWS',r.lifecycle_transition_rows::numeric,NULL,'ROWS','Lifecycle transitions.'),('M2_8_LATEST_ROWS','LATEST_ROWS',r.latest_rows::numeric,NULL,'ROWS','Latest rows.'),('M2_8_ARCHIVE_ROWS','ARCHIVE_ROWS',r.archive_rows::numeric,NULL,'ROWS','Archive rows.'),('M2_8_COMPARISON_ROWS','COMPARISON_ROWS',r.comparison_rows::numeric,NULL,'ROWS','Matched comparisons.'),('M2_8_CANONICAL_ENTITIES','CANONICAL_ENTITIES',r.canonical_entities::numeric,NULL,'ROWS','Canonical entities.'),('M2_8_PROCESSED_PAYMENT_AMOUNT','PROCESSED_PAYMENT_AMOUNT',r.processed_payment_amount::numeric,NULL,'USD','Synthetic processed amount.'),('M2_8_ENDING_EXPOSURE_AMOUNT','ENDING_EXPOSURE_AMOUNT',r.ending_simulated_exposure_amount::numeric,NULL,'USD','Ending simulated exposure.')) v(evidence_code,metric_name,numeric_value,text_value,unit_code,interpretation);
INSERT INTO msbf_ctl.run_evidence(run_id,evidence_code,segment_key,metric_name,metric_value_numeric,metric_value_text,unit_code,status,interpretation) SELECT run_id,evidence_code,segment_key,metric_name,metric_value_numeric,metric_value_text,unit_code,status,interpretation FROM _m28_evidence;
UPDATE msbf_ctl.run_registry SET run_status='M2_8_GENERATED',notes=coalesce(notes,'')||' | M2.8 synthetic servicing execution, payment processing, and lifecycle control generated.' WHERE run_id=(SELECT run_id FROM _m28_ctx);
INSERT INTO _m28_result SELECT r.module1_run_id,'M2_8_GENERATED',r.policy_rows,r.outcome_rows,r.action_rows,r.lifecycle_state_rows,r.reason_rows,r.source_rows,r.execution_rows,r.payment_event_rows,r.lifecycle_transition_rows,r.portfolio_summary_rows,r.latest_rows,r.archive_rows,r.comparison_rows,r.registry_rows,r.no_processing_required_rows,r.temporary_processing_rows,r.review_hold_rows,r.settled_event_rows,r.returned_event_rows,r.retry_event_rows,r.initial_transition_rows,r.payment_transition_rows,r.checkpoint_transition_rows,r.processing_authorized_amount,r.review_hold_amount,(SELECT max(standard_daily_payment_amount) FROM _m28_payment),(SELECT max(scheduled_payment_amount) FROM _m28_payment),r.scheduled_payment_amount,r.processed_payment_amount,r.returned_payment_amount,r.retry_payment_amount,r.ending_simulated_exposure_amount,367,d.actual_canonical_entities,d.row_level_mismatches,d.stress_processing_permission_improvements,d.stress_priority_improvements,d.stress_exposure_improvements,r.policy_set_hash,r.outcome_set_hash,r.action_set_hash,r.lifecycle_state_set_hash,r.reason_set_hash,r.source_set_hash,r.execution_set_hash,r.payment_event_set_hash,r.lifecycle_transition_set_hash,r.portfolio_summary_set_hash,r.latest_set_hash,r.archive_set_hash,r.contract_set_hash,r.combined_set_hash,'PASS' FROM msbf_ctl.m2_8_servicing_execution_contract_registry r CROSS JOIN _m28_diag d WHERE r.module1_run_id=(SELECT run_id FROM _m28_ctx);
COMMIT;
SELECT * FROM _m28_result;
